    c.strokeStyle = "#160f17"; c.lineWidth = 1.2; c.beginPath(); c.arc(q.x, q.y, 6.3 * s, 0, TAU); c.stroke();
  }
  // foam at the waterline
  c.save(); c.globalCompositeOperation = "screen";
  for (let i = 0; i < 60; i++) {
    const x = ox + rnd(p, -100, 100) * s, y = wl - 5 + rnd(p, 0, 4);
    c.strokeStyle = rgba("#9aa6e6", rnd(p, 0.15, 0.4)); c.lineWidth = 0.7;
    c.beginPath(); c.moveTo(x, y); c.lineTo(x + rnd(p, 3, 10), y); c.stroke();
  }
  c.restore();
