  const pg = c.createLinearGradient(0, 330, 0, ART_H);
  pg.addColorStop(0, rgba("#5a6098", 0.0)); pg.addColorStop(0.2, rgba("#5a6098", 0.35)); pg.addColorStop(1, rgba("#3b4070", 0.6));
  c.fillStyle = pg;
