const SCENES: Record<string, (p: P) => void> = {
  "tortoise-and-hare": p => meadow(p, true),
  "noahs-ark": ark,
  "three-little-pigs": pigs,
  "little-red-riding-hood": redHood,
};

const LABELS: Record<string, string> = {
  "tortoise-and-hare": "A tortoise and a hare in a moonlit meadow",
  "noahs-ark": "The ark glowing on a moonlit sea, with a dove and a pale moonbow",
  "three-little-pigs": "Three little houses with glowing windows while a wolf howls at the moon",
  "little-red-riding-hood": "Little Red Riding Hood with a lantern on a path through the night forest",
};

export function sceneLabel(kind: string) {
  return LABELS[kind] ?? "A moonlit meadow full of fireflies";
}

export function paintScene(canvas: HTMLCanvasElement, kind: string, width = 1440) {
  canvas.width = width;
  canvas.height = Math.round((width * ART_H) / ART_W);
  const c = canvas.getContext("2d");
  if (!c) return;
  const s = width / ART_W;
  c.setTransform(s, 0, 0, s, 0, 0);
  const r = mulberry32(hash(kind));
  const p: P = { c, r, n: new Noise(r), light: { x: 300, y: 100 }, s };
  (SCENES[kind] ?? (q => meadow(q, false)))(p);
  finish(p, canvas);
}

